(function () {
  const LX = globalThis.LX;
  const { T, H, P, STORY, TIP, WARN, FUN, BIG, JOB, CMD, TABLE, ANAT, PRE, THINK, STEPS, TRY } = LX.b;
  const { mcq, cmd } = LX.Q;
  const M = LX.M;
  const host = (sh, h) => LX.hostShell(sh, h);
  const hasPkg = (sh, h, p) => host(sh, h).installed.has(p);
  const fileOn = (sh, h, p) => {
    const n = host(sh, h).fs.lookup(p);
    return n && n.t === 'f' ? n.content : null;
  };
  const here = (name, lines) => `cat > ${name} <<'XEOF'\n${lines.join('\n')}\nXEOF`;

  const KEYS = ['sudo apt install -y ansible sshpass', 'ssh-keygen -t ed25519 -N "" -f ~/.ssh/id_ed25519 -q', 'sshpass -p lab ssh-copy-id learner@web01.lab.local', 'sshpass -p lab ssh-copy-id learner@db01'];
  const INV = ['mkdir -p ~/ans', 'cd ~/ans', 'printf "[defaults]\\ninventory = ./inventory.ini\\nremote_user = learner\\nhost_key_checking = False\\n" > ansible.cfg', 'printf "[web]\\nweb01.lab.local\\n\\n[db]\\ndb01\\n\\n[prod:children]\\nweb\\ndb\\n" > inventory.ini'];
  const LAB = KEYS.concat(INV);

  const SITE = [
    '---',
    '- name: Web server',
    '  hosts: web',
    '  become: true',
    '  tasks:',
    '    - name: Install nginx',
    '      ansible.builtin.apt:',
    '        name: nginx',
    '        state: present',
    '        update_cache: true',
    '    - name: Publish the home page',
    '      ansible.builtin.copy:',
    '        content: "Managed by Ansible\\n"',
    '        dest: /var/www/html/index.html',
    '        mode: "0644"',
    '      notify: Restart nginx',
    '    - name: Make sure nginx runs now and at boot',
    '      ansible.builtin.service:',
    '        name: nginx',
    '        state: started',
    '        enabled: true',
    '  handlers:',
    '    - name: Restart nginx',
    '      ansible.builtin.service:',
    '        name: nginx',
    '        state: restarted',
  ];
  const SITE_FIX = [here('site.yml', SITE), 'ansible-playbook --syntax-check site.yml', 'ansible-playbook site.yml', 'ansible-playbook site.yml', 'ansible web -a "cat /var/www/html/index.html"'];

  const BROKEN = ['---', '- hosts: web', '  become: true', '  vars:', '    pkg_name: tree', '  tasks:', '    - name: Install the tool', '      ansible.builtin.apt:', '        name: "{{ pkgname }}"', '        state: present'];
  const BROKEN_LAB = LAB.concat([here('fix.yml', BROKEN)]);
  const BROKEN_FIX = ['cd ~/ans', 'ansible-playbook fix.yml', 'sed -i "s/pkgname/pkg_name/" fix.yml', 'ansible-playbook fix.yml'];

  const USERS = ['---', '- name: Users and message of the day', '  hosts: web', '  become: true', '  vars:', '    env_name: staging', '    team: [asha, ravi]', '  tasks:', '    - name: Create the team users', '      ansible.builtin.user:', '        name: "{{ item }}"', '        shell: /bin/bash', '        state: present', '      loop: "{{ team }}"', '    - name: Message of the day', '      ansible.builtin.template:', '        src: motd.j2', '        dest: /etc/motd', '        mode: "0644"'];
  const MOTD = ['Welcome to {{ inventory_hostname }} ({{ env_name }})', 'Team members:', '{% for u in team %}', ' - {{ u }}', '{% endfor %}'];
  const USERS_LAB = LAB.concat(['mkdir -p ~/ans/templates', 'cd ~/ans', here('templates/motd.j2', MOTD)]);
  const USERS_FIX = ['cd ~/ans', here('users.yml', USERS), 'ansible-playbook users.yml', 'ansible web -a "cat /etc/motd"'];

  const ROLE_FIX = [
    'cd ~/ans',
    'ansible-galaxy init roles/webserver',
    here('roles/webserver/tasks/main.yml', ['---', '- name: Install nginx', '  ansible.builtin.apt:', '    name: nginx', '    state: present', '- name: Publish the page', '  ansible.builtin.template:', '    src: index.html.j2', '    dest: /var/www/html/index.html', '  notify: Restart nginx']),
    'echo "<h1>{{ site_title }} on {{ inventory_hostname }}</h1>" > roles/webserver/templates/index.html.j2',
    'echo "site_title: Acme Intranet" > roles/webserver/defaults/main.yml',
    here('roles/webserver/handlers/main.yml', ['---', '- name: Restart nginx', '  ansible.builtin.service:', '    name: nginx', '    state: restarted']),
    here('roles.yml', ['---', '- hosts: web', '  become: true', '  roles:', '    - webserver']),
    'ansible-playbook roles.yml',
    'ansible web -a "cat /var/www/html/index.html"',
  ];

  const VAULT_FIX = [
    'cd ~/ans',
    'printf "db_password: S3cretPass\\n" > secrets.yml',
    'ansible-vault encrypt secrets.yml',
    here('dbconf.yml', ['---', '- hosts: db', '  become: true', '  vars_files:', '    - secrets.yml', '  tasks:', '    - name: Write the app config', '      ansible.builtin.copy:', '        content: "password={{ db_password }}\\n"', '        dest: /etc/app.conf', '        mode: "0600"', '      no_log: true']),
    'ansible-playbook dbconf.yml --ask-vault-pass',
  ];

  const UNREACH_LAB = ['sudo apt install -y ansible sshpass', 'ssh-keygen -t ed25519 -N "" -f ~/.ssh/id_ed25519 -q', 'sshpass -p lab ssh-copy-id learner@web01.lab.local'].concat(INV);
  const UNREACH_FIX = ['cd ~/ans', 'ansible all -m ping', 'sshpass -p lab ssh-copy-id learner@db01', 'ansible all -m ping'];

  const HTOP_FIX = ['cd ~/ans', 'ansible all -b -m apt -a "name=htop state=present"'];

  LX.topics.push({
    id: 'ansible',
    part: 5,
    no: 37,
    key: '⚙',
    mins: 90,
    title: T('Ansible: Configuration Management and Automation', 'Ansible: Configuration Management aur Automation'),
    blurb: T('Manage ten or a hundred servers like one. Inventory, ad-hoc commands, playbooks, idempotency, variables and templates, handlers, roles, Vault for secrets, and how to debug a playbook.', 'Das ya sau servers ko ek ki tarah sambhalo. Inventory, ad-hoc commands, playbooks, idempotency, variables aur templates, handlers, roles, secrets ke liye Vault, aur playbook debug karna.'),
    blocks: [
      BIG(
        'Logging in to one server and typing commands is fine. Doing it on 40 servers, identically, every time, and being able to prove what changed, is not. **Ansible** lets you describe the state you want ("nginx installed, this page published, service running") in a plain text file, and it makes every server match. It is **agentless**: nothing to install on the servers, it just uses **SSH** and the Python that is already there. It is also **idempotent**: run it ten times and the result is the same, it only changes what is not yet right. This is "infrastructure as code", and Ansible is the tool most Linux job posts mention first.',
        'Ek server mein login karke commands type karna theek hai. 40 servers par ek jaisa, har baar, aur saabit kar paana ki kya badla, theek nahi. **Ansible** tumhe chahi hui halat ("nginx installed, ye page published, service chal rahi") ek saadi text file mein likhne deta hai, aur har server ko usse match karwa deta hai. Ye **agentless** hai: servers par kuch install nahi karna, bas **SSH** aur pehle se maujood Python use karta hai. Ye **idempotent** bhi hai: das baar chalao, natija ek jaisa, sirf wahi badalta hai jo abhi theek nahi. Isse "infrastructure as code" kehte hain, aur Linux job posts mein sabse pehle Ansible ka hi naam aata hai.'
      ),
      STORY(
        'Imagine you manage 40 hotel rooms. Walking to each room to straighten the bed, check the minibar and swap the towels is slow and every room ends up a little different. Instead you write one **housekeeping checklist** ("bed made, towels fresh, minibar stocked") and give it to a staff member who visits every room and only fixes what does not match. Rooms that are already right are left alone (idempotent), and the checklist doubles as documentation.',
        'Socho tum 40 hotel rooms sambhalte ho. Har room mein jaakar bed seedha karna, minibar dekhna aur towels badalna dheema hai aur har room thoda alag ban jata hai. Iske bajay tum ek **housekeeping checklist** likhte ho ("bed bana, towels taaze, minibar bhara") aur staff ko dete ho jo har room mein jaakar sirf wahi theek karta hai jo match nahi karta. Jo rooms pehle se theek hain unhe chhoda jata hai (idempotent), aur checklist documentation bhi ban jati hai.'
      ),
      TABLE(
        [
          ['control node', 'the machine you run ansible from (your laptop or a jump host); needs Ansible installed', 'wo machine jahan se ansible chalate ho (laptop ya jump host); Ansible install chahiye'],
          ['managed node', 'a server being configured: needs only SSH and Python', 'jis server ko configure kiya ja raha: sirf SSH aur Python chahiye'],
          ['inventory', 'the list of hosts, organised in groups (web, db, prod)', 'hosts ki list, groups mein (web, db, prod)'],
          ['module', 'a small program that does one job idempotently: apt, copy, service, user, file, template', 'chhota program jo ek kaam idempotent tareeke se karta hai: apt, copy, service, user, file, template'],
          ['task', 'one call of a module with arguments, with a human name', 'ek module ki ek call arguments ke saath, insaani naam ke saath'],
          ['play / playbook', 'a play maps a group of hosts to tasks; a playbook is a YAML file with one or more plays', 'play hosts ke group ko tasks se jodta hai; playbook ek YAML file hai jisme ek ya zyada plays'],
          ['handler', 'a task that runs only when notified by a change (restart nginx only if the config changed)', 'task jo sirf badlav se notify hone par chalta hai (config badli tabhi nginx restart)'],
          ['variable / fact', 'a variable is a value you define; facts are values Ansible discovers about each server (OS, IP, memory)', 'variable tumhari di hui value; facts wo values jo Ansible har server ke baare mein khud pata karta hai (OS, IP, memory)'],
          ['role', 'a reusable folder structure that bundles tasks, templates, defaults and handlers', 'dobara use hone layak folder structure jisme tasks, templates, defaults aur handlers bundled'],
          ['Vault', 'encrypts secret files (passwords, keys) so they can safely live in Git', 'secret files (passwords, keys) encrypt karta hai taaki Git mein safely rahein'],
        ],
        'Word',
        'Shabd'
      ),
      H('Setup: install, keys and an inventory', 'Setup: install, keys aur inventory'),
      P('Ansible logs in over SSH, so first make sure **key-based login works** to every server (the SSH lesson). In this sandbox the practice servers are `web01.lab.local` and `db01`; the password for ssh-copy-id is whatever you type (the lab accepts any). `sshpass` is a real tool that feeds a password to a prompt: handy in labs and bootstrap scripts, never as a daily habit.', 'Ansible SSH se login karta hai, isliye pehle pakka karo ki har server par **key-based login chalta hai** (SSH lesson). Is sandbox mein practice servers `web01.lab.local` aur `db01` hain; ssh-copy-id ka password jo bhi type karo (lab koi bhi leta hai). `sshpass` asli tool hai jo password prompt ko password khilata hai: labs aur bootstrap scripts mein kaam ka, rozmarra ki aadat nahi.'),
      CMD(KEYS.concat(['ansible --version | head -n 2']), 'The key pair lives on the control node; ssh-copy-id puts the public half on each managed node. After this, ssh web01.lab.local logs you in without a password, which is exactly what Ansible needs.', 'Key pair control node par rehti hai; ssh-copy-id public hissa har managed node par rakhta hai. Iske baad ssh web01.lab.local bina password login hota hai, jo Ansible ko chahiye.'),
      P('The **inventory** names your hosts and groups. INI is the simplest format; `[prod:children]` makes a group of groups. A small `ansible.cfg` in the project folder sets defaults so that you do not retype `-i` every time. Keep the whole folder in Git.', '**Inventory** tumhare hosts aur groups ke naam rakhti hai. INI sabse saral format hai; `[prod:children]` groups ka group banata hai. Project folder mein chhoti `ansible.cfg` defaults set karti hai taaki har baar `-i` na likhna pade. Poora folder Git mein rakho.'),
      CMD(INV.concat(['cat inventory.ini', 'ansible-inventory --graph', 'ansible all --list-hosts', 'ansible prod -m ping']), 'ansible-inventory --graph draws the groups. The pattern before -m chooses the hosts: all, a group (web), a host, a union (web:db), or an exclusion (all:!db). ping is NOT ICMP: it logs in over SSH and checks that Python works, and answers "pong". Seeing SUCCESS/pong means the whole chain works.', 'ansible-inventory --graph groups ka naqsha banata hai. -m se pehle ka pattern hosts chunta hai: all, group (web), host, union (web:db), ya exclusion (all:!db). ping ICMP NAHI hai: ye SSH se login karke check karta hai ki Python chalta hai, aur "pong" kehta hai. SUCCESS/pong dikhe to poori chain chal rahi hai.'),
      TIP('If the ping says UNREACHABLE, debug it like SSH: can you `ssh learner@host` by hand? Right user? Key installed? Hostname resolves? Ansible adds nothing magic on top: 90% of "Ansible problems" are SSH problems.', 'Ping UNREACHABLE kahe to SSH ki tarah debug karo: kya haath se `ssh learner@host` chalta hai? Sahi user? Key lagi hai? Hostname resolve hota hai? Ansible upar se koi jaadu nahi jodta: 90% "Ansible problems" SSH problems hain.'),
      H('Ad-hoc commands: one task, right now', 'Ad-hoc commands: ek kaam, abhi'),
      ANAT([
        ['ansible', 'cmd', 'the ad-hoc runner', 'ad-hoc chalane wala'],
        ['web', 'arg', 'which hosts: a group, a host or a pattern', 'kaun se hosts: group, host ya pattern'],
        ['-b', 'opt', 'become: run as root through sudo', 'become: sudo ke zariye root ki tarah chalao'],
        ['-m apt', 'opt', 'the module to use (default: command)', 'kaun sa module (default: command)'],
        ['-a "name=htop state=present"', 'opt', 'the module arguments: key=value pairs, or a shell command for command/shell', 'module ke arguments: key=value jode, ya command/shell ke liye shell command'],
        ['--limit / -l', 'opt', 'narrow the hosts further', 'hosts aur kam karo'],
      ]),
      CMD(['cd ~/ans', 'ansible web -a "uptime"', 'ansible all -m setup -a "filter=ansible_distribution*" -o', 'ansible all -b -m apt -a "name=htop state=present"', 'ansible all -b -m apt -a "name=htop state=present"', 'ansible web -b -m user -a "name=deploy shell=/bin/bash"', 'ansible web -b -m file -a "path=/opt/app state=directory mode=0755"', 'ansible web -b -m service -a "name=nginx state=started"'], 'The first apt run says CHANGED (it installed htop), the identical second run says SUCCESS/changed=false: that is idempotency. Ad-hoc is perfect for quick facts and one-off jobs; the moment you do something twice, write a playbook. The setup module returns "facts" (OS, IP, memory...). -o prints one line per host.', 'Pehli apt run CHANGED kehti hai (htop install kiya), wahi doosri run SUCCESS/changed=false: yahi idempotency hai. Ad-hoc jaldi ke sawalon aur ek baar ke kaamon ke liye badhiya hai; jaise hi kuch do baar karo, playbook likho. setup module "facts" deta hai (OS, IP, memory...). -o har host ki ek line chhapta hai.'),
      WARN('Prefer real modules (`apt`, `copy`, `user`, `service`, `file`) over `command`/`shell`. A module checks the current state and acts only if needed; `shell: apt-get install nginx` runs every time and always reports "changed". Use `command`/`shell` only when no module exists, and then add `creates:` or `changed_when:` to keep it honest.', 'Asli modules (`apt`, `copy`, `user`, `service`, `file`) ko `command`/`shell` par prefer karo. Module maujooda halat dekhta hai aur sirf zaroorat par kaam karta hai; `shell: apt-get install nginx` har baar chalta hai aur hamesha "changed" kehta hai. `command`/`shell` tabhi jab koi module na ho, aur tab `creates:` ya `changed_when:` jodkar use imaandar rakho.'),
      H('Your first playbook', 'Tumhara pehla playbook'),
      P('A playbook is **YAML**: indentation with **spaces** (never tabs) is the structure, `-` starts a list item, `key: value` is a mapping. A wrong indent is the number-one beginner error: use `--syntax-check` and a good editor. Read this one top to bottom: it states a *desired state*, not a script of steps.', 'Playbook **YAML** hai: **spaces** se indentation (kabhi tabs nahi) hi structure hai, `-` list item shuru karta hai, `key: value` mapping hai. Galat indent beginners ki number-ek galti hai: `--syntax-check` aur achha editor use karo. Ise upar se neeche padho: ye *chahi hui halat* batata hai, steps ki script nahi.'),
      PRE(SITE.join('\n')),
      CMD(['cd ~/ans', here('site.yml', SITE), 'ansible-playbook --syntax-check site.yml', 'ansible-playbook site.yml'], 'Read the output: PLAY, then each TASK with ok / changed per host, then the PLAY RECAP counters. The first run changes things (installs nginx, writes the page, the handler restarts nginx because the page changed).', 'Output padho: PLAY, phir har TASK ke saath har host ka ok / changed, phir PLAY RECAP ke counters. Pehli run cheezein badalti hai (nginx install, page likhna, handler nginx restart karta hai kyunki page badla).'),
      CMD(['ansible-playbook site.yml', 'ansible web -a "cat /var/www/html/index.html"', 'ansible web -b -m copy -a "content=vandalised\\n dest=/var/www/html/index.html"', 'ansible-playbook site.yml --check --diff', 'ansible-playbook site.yml', 'ansible web -a "cat /var/www/html/index.html"'], 'The second run shows changed=0: nothing to do. Then somebody "vandalises" the page by hand: a --check (dry run) shows what WOULD change, and a normal run repairs the drift and restarts nginx through the handler. This is the real value: the playbook is the truth, and re-running it enforces it.', 'Doosri run changed=0 dikhati hai: kuch karna nahi. Phir koi haath se page "kharab" kar deta hai: --check (dry run) dikhata hai KYA badlega, aur normal run drift theek karti hai aur handler se nginx restart. Asli keemat yahi hai: playbook sach hai, aur dobara chalane se wo lagu hota hai.'),
      TABLE(
        [
          ['--syntax-check', 'validate YAML and structure without connecting', 'bina connect kiye YAML aur structure check'],
          ['--check (-C) [--diff]', 'dry run: report what would change [and show file differences]', 'dry run: batao kya badlega [aur file ke antar dikhao]'],
          ['--list-tasks / --list-hosts', 'show what would run and where', 'dikhao kya aur kahan chalega'],
          ['--limit db01', 'run on a subset of the inventory', 'inventory ke ek hisse par chalao'],
          ['--tags config / --skip-tags x', 'run only tasks with a tag / skip them', 'sirf tag wale tasks chalao / chhodo'],
          ['-e "name=value"  /  -e @file.yml', 'extra variables (highest priority)', 'extra variables (sabse upar ki priority)'],
          ['-v / -vvv', 'show the returned data / connection debugging', 'wapas aaya data / connection debugging dikhao'],
          ['--start-at-task "name"', 'resume at a task after fixing a failure', 'failure theek karne ke baad ek task se aage badho'],
        ],
        'Option',
        'Option'
      ),
      H('Variables, facts, conditions, loops, templates', 'Variables, facts, conditions, loops, templates'),
      P('**Variables** make one playbook serve many servers. They can come from `vars:` in the play, from `group_vars/<group>.yml` and `host_vars/<host>.yml` files next to the inventory, from facts, or from `-e` on the command line. Use them in tasks with `{{ name }}`. **Loops** repeat a task over a list, **when:** runs a task only if a condition is true, **register** saves a task\'s result, and **templates** (Jinja2) build files from variables.', '**Variables** ek playbook ko kai servers ke liye kaam ka banate hain. Ye play ke `vars:` se, inventory ke paas `group_vars/<group>.yml` aur `host_vars/<host>.yml` files se, facts se, ya command line ke `-e` se aa sakte hain. Tasks mein `{{ name }}` se use karo. **Loops** list par task dohrate hain, **when:** task tabhi chalata hai jab condition sach ho, **register** task ka result save karta hai, aur **templates** (Jinja2) variables se files banate hain.'),
      CMD(['cd ~/ans', 'mkdir -p group_vars templates', 'printf "ntp_server: pool.ntp.org\\nenv_name: production\\n" > group_vars/all.yml', 'printf "env_name: database-tier\\n" > group_vars/db.yml', here('templates/motd.j2', MOTD), here('users.yml', USERS.concat(['    - name: A note only for the db tier', '      ansible.builtin.lineinfile:', '        path: /etc/motd', '        line: "Backups run at 02:30"', '      when: "\'db\' in group_names"'])).replace('hosts: web', 'hosts: prod'), 'ansible-playbook users.yml', 'ansible all -a "cat /etc/motd"'], 'group_vars/all.yml applies to every host, group_vars/db.yml overrides it for the db group. The play sets env_name itself to "staging", so the play variable wins here: know the precedence (extra vars > play vars > inventory/group vars > role defaults). The template loops over the team list; the lineinfile task runs only on hosts in the db group.', 'group_vars/all.yml har host par lagu hai, group_vars/db.yml db group ke liye use override karta hai. Play ne env_name khud "staging" set kiya, isliye yahan play variable jeetta hai: precedence jaano (extra vars > play vars > inventory/group vars > role defaults). Template team list par loop karta hai; lineinfile task sirf db group ke hosts par chalta hai.'),
      TABLE(
        [
          ['when: ansible_os_family == "Debian"', 'run only on Debian-family hosts (a fact)', 'sirf Debian-family hosts par chalao (ek fact)'],
          ['loop: "{{ users }}"  with  {{ item }}', 'repeat the task for each element', 'har element ke liye task dohrao'],
          ['register: result  then  result.stdout', 'capture a command\'s output for later tasks', 'baad ke tasks ke liye command ka output pakdo'],
          ['ansible.builtin.debug: var=result', 'print a variable: the print-statement of playbooks', 'variable chhapo: playbooks ka print-statement'],
          ['changed_when / failed_when', 'tell Ansible what counts as a change or a failure for command-style tasks', 'command-style tasks mein kya badlav ya failure maana jaye ye batao'],
          ['ignore_errors: true', 'carry on after a failure (use sparingly; prefer block/rescue)', 'failure ke baad aage badho (kam use karo; block/rescue behtar)'],
          ['tags: [config]', 'label tasks so that --tags can select them', 'tasks par label lagao taaki --tags unhe chun sake'],
        ],
        'Keyword',
        'Keyword'
      ),
      H('Handling errors: block, rescue, always', 'Errors sambhalna: block, rescue, always'),
      CMD(['cd ~/ans', here('blk.yml', ['---', '- hosts: web', '  tasks:', '    - block:', '        - name: A step that fails', '          ansible.builtin.command: /bin/false', '      rescue:', '        - name: Recover', '          ansible.builtin.debug:', '            msg: "recovering"', '      always:', '        - name: Always clean up', '          ansible.builtin.debug:', '            msg: "cleanup done"']), 'ansible-playbook blk.yml'], 'block/rescue/always is try/catch/finally for playbooks: when the block fails the rescue tasks run, and always runs regardless. The RECAP counts it as rescued=1. A failed task stops that host for the rest of the play unless you handle it.', 'block/rescue/always playbooks ka try/catch/finally hai: block fail ho to rescue tasks chalte hain, aur always har haal mein chalta hai. RECAP ise rescued=1 ginta hai. Fail hua task us host ko play ke baaki hisse ke liye rok deta hai jab tak tum use sambhalo nahi.'),
      H('Roles: reusable building blocks', 'Roles: dobara use hone wale building blocks'),
      P('When playbooks grow, split them into **roles**: a standard folder layout (`tasks/`, `handlers/`, `templates/`, `files/`, `defaults/`, `vars/`, `meta/`) that Ansible knows how to load. A play then just lists `roles: [webserver, common]`. `ansible-galaxy init` creates the skeleton; public roles on Ansible Galaxy follow the same layout (not reachable from this sandbox).', 'Playbooks bade ho jaayen to unhe **roles** mein todo: standard folder layout (`tasks/`, `handlers/`, `templates/`, `files/`, `defaults/`, `vars/`, `meta/`) jise Ansible load karna jaanta hai. Phir play bas `roles: [webserver, common]` likhta hai. `ansible-galaxy init` skeleton banata hai; Ansible Galaxy ke public roles wahi layout follow karte hain (is sandbox se nahi pahunch sakte).'),
      CMD(ROLE_FIX, 'The role keeps its tasks, template, default variable (site_title) and handler together, and the playbook roles.yml is three lines. Defaults are the lowest-priority variables: an inventory or -e value overrides them, which is what makes a role reusable. Try: ansible-playbook roles.yml -e "site_title=Hello".', 'Role apne tasks, template, default variable (site_title) aur handler saath rakhta hai, aur playbook roles.yml teen line ka hai. Defaults sabse kam priority ke variables hain: inventory ya -e ki value unhe override karti hai, isi se role dobara use hone layak banta hai. Try karo: ansible-playbook roles.yml -e "site_title=Hello".'),
      H('Secrets: Ansible Vault', 'Secrets: Ansible Vault'),
      P('Passwords, API keys and certificates must not sit in plain text in Git. **ansible-vault** encrypts a file (or a single value with `encrypt_string`) with a password; playbooks read it transparently when you supply the vault password (`--ask-vault-pass` or `--vault-password-file`). Commit the encrypted file; keep the vault password somewhere else (a password manager, CI secret). The sandbox uses a teaching cipher with the real file format; the commands and workflow are identical to the real thing.', 'Passwords, API keys aur certificates Git mein plain text mein nahi hone chahiye. **ansible-vault** file ko (ya `encrypt_string` se ek value ko) password se encrypt karta hai; vault password dene par (`--ask-vault-pass` ya `--vault-password-file`) playbooks use khud padh lete hain. Encrypted file commit karo; vault password kahin aur rakho (password manager, CI secret). Sandbox real file format ke saath ek teaching cipher use karta hai; commands aur workflow asli jaise hi hain.'),
      CMD(VAULT_FIX.concat(['head -n 2 secrets.yml', 'ansible-vault view secrets.yml', 'ansible db -b -a "cat /etc/app.conf"']), 'You will be asked for a New Vault password (twice) and later for the Vault password. The encrypted file starts with $ANSIBLE_VAULT;1.1;AES256 and is safe to commit. no_log: true keeps the secret out of the playbook output. view, edit, decrypt and rekey manage the file afterwards.', 'Tumse New Vault password (do baar) aur baad mein Vault password poocha jayega. Encrypted file $ANSIBLE_VAULT;1.1;AES256 se shuru hoti hai aur commit karne ke liye surakshit hai. no_log: true secret ko playbook output se door rakhta hai. Baad mein view, edit, decrypt aur rekey file sambhalte hain.'),
      H('When it goes wrong', 'Jab kuch galat ho'),
      TABLE(
        [
          ['UNREACHABLE! ... Permission denied (publickey)', 'SSH problem: key not on the server, wrong user (ansible_user), wrong host name. Test with ssh by hand', 'SSH problem: key server par nahi, galat user (ansible_user), galat host naam. Haath se ssh se test karo'],
          ['"Missing sudo password" / "become" failed', 'the task needs root: add become: true (and sudo rights or -K for the password)', 'task ko root chahiye: become: true jodo (aur sudo adhikar ya password ke liye -K)'],
          ['"mapping values are not allowed here", "could not find expected \':\'"', 'YAML indentation, a missing space after a colon, or a tab', 'YAML indentation, colon ke baad space ki kami, ya tab'],
          ["'x' is undefined", 'typo in a variable name, or a variable defined in a place this play does not load. Use debug: var=', 'variable naam mein typo, ya aise jagah define jo ye play load nahi karta. debug: var= use karo'],
          ["couldn't resolve module/action", 'misspelled module name or a missing collection', 'module naam galat ya collection missing'],
          ['task shows changed on EVERY run', 'a shell/command task without creates:/changed_when:, or a template with changing content (timestamps)', 'shell/command task jisme creates:/changed_when: nahi, ya badalte content wala template (timestamps)'],
          ['handler did not run', 'nothing changed (so no notify), or the play failed before the handlers; use --force-handlers', 'kuch badla nahi (to notify nahi), ya handlers se pehle play fail; --force-handlers use karo'],
        ],
        'Symptom',
        'Lakshan'
      ),
      CMD(BROKEN_LAB.slice(LAB.length).concat(['ansible-playbook fix.yml', 'grep -n pkg fix.yml']), 'The classic typo: the variable is called pkg_name but the task uses pkgname. Ansible stops with an "undefined variable" error and names the variable. Fix the name and run again.', 'Classic typo: variable ka naam pkg_name hai par task pkgname use karta hai. Ansible "undefined variable" error ke saath ruk jata hai aur variable ka naam batata hai. Naam theek karo aur dobara chalao.'),
      H('Good habits and how this fits the rest', 'Achhi aadatein aur baaki se kaise judta hai'),
      STEPS([
        ['Everything in **Git**: inventory, playbooks, roles, group_vars (secrets vaulted). Changes go through review like code (previous lesson).', 'Sab kuch **Git** mein: inventory, playbooks, roles, group_vars (secrets vaulted). Badlav code ki tarah review se guzarte hain (pichhla lesson).'],
        ['**Name every task** so the output reads like a report, and prefer modules to shell.', '**Har task ka naam rakho** taaki output report jaisa padhe, aur shell ke bajay modules prefer karo.'],
        ['**Test safely**: `--syntax-check`, `--check --diff`, then a `--limit` to one or two hosts (a canary) before the whole fleet.', '**Surakshit test karo**: `--syntax-check`, `--check --diff`, phir poore fleet se pehle ek-do hosts par `--limit` (canary).'],
        ['Keep production and staging **inventories separate** (`inventories/prod`, `inventories/staging`) with the same roles.', 'Production aur staging **inventories alag** rakho (`inventories/prod`, `inventories/staging`), roles wahi.'],
        ['Run it from CI or a tool such as AWX/Ansible Automation Platform, never from "whoever has the right laptop". Lint with `ansible-lint`.', 'Ise CI ya AWX/Ansible Automation Platform jaise tool se chalao, "jiske paas sahi laptop ho" usse nahi. `ansible-lint` se lint karo.'],
      ]),
      TABLE(
        [
          ['Terraform / OpenTofu', 'creates the infrastructure (servers, networks, cloud services); Ansible then configures what runs on it. They complement each other', 'infrastructure banata hai (servers, networks, cloud services); Ansible phir uspar chalne wali cheezein configure karta hai. Ye ek doosre ke poorak hain'],
          ['Puppet, Chef, Salt', 'older/other configuration managers, often agent-based; know the names, the ideas are the same', 'purane/doosre configuration managers, aksar agent-based; naam jaano, vichar wahi hain'],
          ['cloud-init', 'first-boot configuration of a new cloud server (next lessons); often installs the SSH key Ansible then uses', 'naye cloud server ki pehli boot configuration (agle lessons); aksar wo SSH key lagata hai jise Ansible phir use karta hai'],
        ],
        'Tool',
        'Tool'
      ),
      JOB('Typical questions: "What does idempotent mean, and give an example" (applying twice equals applying once: the apt module with state=present), "Why Ansible over a bash script?" (declarative desired state, idempotent modules, inventory/groups, parallel over SSH, readable YAML), "What is the difference between a play, a playbook and a role?", "How do you restart a service only when its config changed?" (notify + handler), "How do you keep secrets safe?" (Ansible Vault, never plain text in Git), "A playbook works on web01 but fails on web02: how do you debug?" (-vvv, --limit web02, check facts and variables, ssh by hand), and "How do you test a change before production?" (--check --diff, staging inventory, canary with --limit).', 'Aam sawal: "Idempotent matlab kya, ek example do" (do baar lagana = ek baar lagana: apt module state=present ke saath), "Bash script ke bajay Ansible kyun?" (declarative desired state, idempotent modules, inventory/groups, SSH par parallel, padhne layak YAML), "Play, playbook aur role mein antar?", "Service sirf config badalne par restart kaise karoge?" (notify + handler), "Secrets surakshit kaise rakhoge?" (Ansible Vault, Git mein plain text kabhi nahi), "Playbook web01 par chalta hai par web02 par fail: debug kaise karoge?" (-vvv, --limit web02, facts aur variables dekho, haath se ssh), aur "Production se pehle badlav ka test kaise karoge?" (--check --diff, staging inventory, --limit se canary).'),
      THINK('A colleague says: "I will just write a bash loop that ssh-es to every server and runs apt install." Name three things Ansible gives you that the loop does not.', 'Ek colleague kehta hai: "Main bas ek bash loop likh dunga jo har server par ssh karke apt install chalaye." Teen cheezein batao jo Ansible deta hai aur loop nahi.', 'Idempotency (safe to re-run, only changes what differs), a clear report of ok/changed/failed per host with a recap, grouping and variables per group/host, parallel execution, check mode to preview, handlers, and a readable file that documents the desired state and can be reviewed in Git. A loop also stops or half-finishes on the first dead host without telling you what state each server is in.', 'Idempotency (dobara chalana surakshit, sirf antar badalta hai), har host ke ok/changed/failed ka saaf report recap ke saath, groups aur per group/host variables, parallel execution, preview ke liye check mode, handlers, aur padhne layak file jo desired state document karti hai aur Git mein review ho sakti hai. Loop pehle mare host par ruk jata ya aadha chhod deta hai aur batata nahi ki har server kis halat mein hai.'),
      H('Cheat sheet', 'Cheat sheet'),
      TABLE([
        ['ansible all -m ping', 'can Ansible log in and run Python everywhere?', 'kya Ansible sab jagah login karke Python chala sakta hai?'],
        ['ansible web -b -m apt -a "name=X state=present"', 'ad-hoc module with sudo', 'sudo ke saath ad-hoc module'],
        ['ansible-inventory --graph', 'see the groups', 'groups dekho'],
        ['ansible-playbook site.yml --syntax-check', 'validate without running', 'bina chalaye validate'],
        ['ansible-playbook site.yml --check --diff', 'dry run with file differences', 'file antar ke saath dry run'],
        ['ansible-playbook site.yml --limit web01 --tags config', 'run a slice', 'ek hissa chalao'],
        ['ansible-playbook site.yml -e "var=value" -vv', 'extra vars and more detail', 'extra vars aur zyada detail'],
        ['ansible-galaxy init roles/NAME', 'role skeleton', 'role ka dhancha'],
        ['ansible-vault encrypt|view|edit|decrypt FILE', 'secrets', 'secrets'],
        ['notify + handlers ; when ; loop ; register ; template', 'the five keywords you will use daily', 'paanch keywords jo roz use karoge'],
      ]),
    ],
    missions: [
      M('ansible-m1', 'Connect Ansible to your servers', 'Ansible ko apne servers se jodo', 'Install ansible and sshpass, create an SSH key, install it on web01.lab.local and db01 (the password is anything; sshpass -p lab ssh-copy-id learner@HOST does it for you), write an inventory ~/ans/inventory.ini with a [web] group (web01.lab.local) and a [db] group (db01), and prove the connection with the ping module on all hosts.', 'ansible aur sshpass install karo, SSH key banao, use web01.lab.local aur db01 par lagao (password kuch bhi; sshpass -p lab ssh-copy-id learner@HOST ye kar deta hai), ~/ans/inventory.ini mein [web] group (web01.lab.local) aur [db] group (db01) likho, aur sab hosts par ping module se connection saabit karo.', 'apt install ansible sshpass ; ssh-keygen ; ssh-copy-id x2 ; inventory.ini ; ansible all -i inventory.ini -m ping', 'apt install ansible sshpass ; ssh-keygen ; ssh-copy-id x2 ; inventory.ini ; ansible all -i inventory.ini -m ping', (sh) => { const f = LX.cat(sh, '/home/learner/ans/inventory.ini'); return /\[web\]/.test(f) && /web01\.lab\.local/.test(f) && /\[db\]/.test(f) && /db01/.test(f) && sh.log.some((r) => /ansible\s+all.*-m\s+ping/.test(r.cmd) && r.code === 0); }, KEYS.concat(['mkdir -p ~/ans', 'cd ~/ans', 'printf "[web]\\nweb01.lab.local\\n\\n[db]\\ndb01\\n" > inventory.ini', 'ansible all -i inventory.ini -m ping']), { testSolve: KEYS.concat(['mkdir -p ~/ans', 'cd ~/ans', 'printf "[web]\\nweb01.lab.local\\n\\n[db]\\ndb01\\n" > inventory.ini', 'ansible all -i inventory.ini -m ping']) }),
      M('ansible-m2', 'One ad-hoc command, every server', 'Ek ad-hoc command, har server', 'The practice project in ~/ans is ready (keys, inventory, ansible.cfg). With ONE ad-hoc command, install the package htop as root on all hosts. (Use the lab button.)', '~/ans mein practice project taiyar hai (keys, inventory, ansible.cfg). EK ad-hoc command se sab hosts par root ki tarah htop package install karo. (Lab button use karo.)', 'ansible all -b -m apt -a "name=htop state=present"', 'ansible all -b -m apt -a "name=htop state=present"', (sh) => hasPkg(sh, 'web01.lab.local', 'htop') && hasPkg(sh, 'db01', 'htop'), LAB.concat(HTOP_FIX), { lab: { setup: LAB, en: 'a project folder with working SSH keys, an inventory with web and db groups, and ansible.cfg.', hi: 'project folder jisme chalti SSH keys, web aur db groups wali inventory aur ansible.cfg hai.' }, testSolve: LAB.concat(HTOP_FIX) }),
      M('ansible-m3', 'Write a playbook and prove it is idempotent', 'Playbook likho aur saabit karo ki idempotent hai', 'In ~/ans write site.yml for the web group (become: true) that installs nginx, publishes a page "Managed by Ansible" in /var/www/html/index.html and makes sure the nginx service is started and enabled. Check the syntax, run it, and run it a second time (it must report nothing changed). (Use the lab button.)', '~/ans mein web group ke liye (become: true) site.yml likho jo nginx install kare, /var/www/html/index.html mein "Managed by Ansible" page publish kare aur nginx service started aur enabled rakhe. Syntax check karo, chalao, aur doosri baar chalao (changed kuch nahi dikhna chahiye). (Lab button use karo.)', 'cat > site.yml (apt + copy + service) ; ansible-playbook --syntax-check site.yml ; ansible-playbook site.yml (twice)', 'cat > site.yml (apt + copy + service) ; ansible-playbook --syntax-check site.yml ; ansible-playbook site.yml (do baar)', (sh) => { const idx = fileOn(sh, 'web01.lab.local', '/var/www/html/index.html'); const runs = sh.log.filter((r) => /ansible-playbook\s+(?!--)\S*site\.yml/.test(r.cmd) || /ansible-playbook\s+site\.yml\s*$/.test(r.cmd)); return hasPkg(sh, 'web01.lab.local', 'nginx') && !!idx && /Managed by Ansible/.test(idx) && runs.length >= 2 && sh.log.some((r) => /--syntax-check/.test(r.cmd)); }, LAB.concat(['cd ~/ans']).concat(SITE_FIX), { lab: { setup: LAB, en: 'the practice project (keys, inventory, ansible.cfg).', hi: 'practice project (keys, inventory, ansible.cfg).' }, testSolve: LAB.concat(['cd ~/ans']).concat(SITE_FIX) }),
      M('ansible-m4', 'Fix a broken playbook', 'Toota hua playbook theek karo', 'The playbook ~/ans/fix.yml should install the package tree on the web group but fails. Run it, read the error, correct the mistake in the file and run it again until tree is installed on web01.lab.local. (Use the lab button.)', '~/ans/fix.yml ko web group par tree package install karna chahiye par fail hota hai. Chalao, error padho, file ki galti theek karo aur tab tak dobara chalao jab tak web01.lab.local par tree install na ho jaye. (Lab button use karo.)', 'ansible-playbook fix.yml ; sed -i "s/pkgname/pkg_name/" fix.yml ; ansible-playbook fix.yml', 'ansible-playbook fix.yml ; sed -i "s/pkgname/pkg_name/" fix.yml ; ansible-playbook fix.yml', (sh) => hasPkg(sh, 'web01.lab.local', 'tree') && sh.log.filter((r) => /ansible-playbook\s+fix\.yml/.test(r.cmd)).length >= 2, BROKEN_LAB.concat(BROKEN_FIX), { lab: { setup: BROKEN_LAB, en: 'a playbook fix.yml with a misspelled variable name.', hi: 'playbook fix.yml jisme variable ka naam galat likha hai.' }, testSolve: BROKEN_LAB.concat(BROKEN_FIX) }),
      M('ansible-m5', 'Variables, a loop and a template', 'Variables, ek loop aur ek template', 'The folder ~/ans/templates already has motd.j2. Write ~/ans/users.yml for the web group (become: true) with the variables env_name: staging and team: [asha, ravi]; a task that creates each user of the team with a loop (user module), and a task that renders the template motd.j2 to /etc/motd with the template module. Run it. (Use the lab button.)', '~/ans/templates mein motd.j2 pehle se hai. Web group ke liye (become: true) ~/ans/users.yml likho jisme variables env_name: staging aur team: [asha, ravi] hon; ek task jo loop se team ke har user ko banaye (user module), aur ek task jo template module se motd.j2 ko /etc/motd mein render kare. Chalao. (Lab button use karo.)', 'vars + loop over team (ansible.builtin.user) + ansible.builtin.template src=motd.j2 dest=/etc/motd ; ansible-playbook users.yml', 'vars + team par loop (ansible.builtin.user) + ansible.builtin.template src=motd.j2 dest=/etc/motd ; ansible-playbook users.yml', (sh) => { const w = host(sh, 'web01.lab.local'); const motd = fileOn(sh, 'web01.lab.local', '/etc/motd') || ''; return !!w.users.asha && !!w.users.ravi && /web01\.lab\.local \(staging\)/.test(motd) && /- asha/.test(motd) && /- ravi/.test(motd); }, USERS_LAB.concat(USERS_FIX), { lab: { setup: USERS_LAB, en: 'the practice project plus templates/motd.j2.', hi: 'practice project aur templates/motd.j2.' }, testSolve: USERS_LAB.concat(USERS_FIX) }),
      M('ansible-m6', 'Turn it into a role', 'Ise role bana do', 'In ~/ans create the role webserver with ansible-galaxy init roles/webserver. Put the tasks (install nginx, template index.html.j2 to /var/www/html/index.html with notify), the template, the default variable site_title and the handler "Restart nginx" in the role, use it from roles.yml for the web group (become: true) and run it. (Use the lab button.)', '~/ans mein ansible-galaxy init roles/webserver se webserver role banao. Role mein tasks (nginx install, index.html.j2 template ko /var/www/html/index.html par notify ke saath), template, default variable site_title aur handler "Restart nginx" rakho, roles.yml se web group (become: true) ke liye use karo aur chalao. (Lab button use karo.)', 'ansible-galaxy init roles/webserver ; fill tasks/handlers/templates/defaults ; roles.yml with roles: [webserver] ; ansible-playbook roles.yml', 'ansible-galaxy init roles/webserver ; tasks/handlers/templates/defaults bharo ; roles.yml mein roles: [webserver] ; ansible-playbook roles.yml', (sh) => { const idx = fileOn(sh, 'web01.lab.local', '/var/www/html/index.html') || ''; const t = LX.cat(sh, '/home/learner/ans/roles/webserver/tasks/main.yml'); return hasPkg(sh, 'web01.lab.local', 'nginx') && /Acme Intranet on web01\.lab\.local/.test(idx) && /nginx/.test(t) && /Restart nginx/.test(LX.cat(sh, '/home/learner/ans/roles/webserver/handlers/main.yml')) && /webserver/.test(LX.cat(sh, '/home/learner/ans/roles.yml')); }, LAB.concat(ROLE_FIX), { lab: { setup: LAB, en: 'the practice project (keys, inventory, ansible.cfg).', hi: 'practice project (keys, inventory, ansible.cfg).' }, testSolve: LAB.concat(ROLE_FIX) }),
      M('ansible-m7', 'Keep a password out of plain text', 'Password ko plain text se door rakho', 'In ~/ans create secrets.yml containing db_password: S3cretPass and encrypt it with ansible-vault (choose any vault password). Then write dbconf.yml for the db group (become: true) that loads secrets.yml with vars_files and writes /etc/app.conf (mode 0600) containing the password, and run it asking for the vault password. (Use the lab button.)', '~/ans mein secrets.yml banao jisme db_password: S3cretPass ho aur use ansible-vault se encrypt karo (koi bhi vault password chuno). Phir db group (become: true) ke liye dbconf.yml likho jo secrets.yml ko vars_files se load kare aur /etc/app.conf (mode 0600) mein password likhe, aur vault password maangte hue chalao. (Lab button use karo.)', 'ansible-vault encrypt secrets.yml ; playbook with vars_files + copy content ; ansible-playbook dbconf.yml --ask-vault-pass', 'ansible-vault encrypt secrets.yml ; vars_files + copy content wala playbook ; ansible-playbook dbconf.yml --ask-vault-pass', (sh) => { const sec = LX.cat(sh, '/home/learner/ans/secrets.yml'); const conf = fileOn(sh, 'db01', '/etc/app.conf') || ''; return /^\$ANSIBLE_VAULT/.test(sec) && !/S3cretPass/.test(sec) && /password=S3cretPass/.test(conf); }, LAB.concat(VAULT_FIX), { lab: { setup: LAB, en: 'the practice project (keys, inventory, ansible.cfg).', hi: 'practice project (keys, inventory, ansible.cfg).' }, testSolve: LAB.concat(VAULT_FIX), testAnswers: ['learner', 'vp123', 'vp123', 'vp123'] }),
      M('ansible-m8', 'One server is UNREACHABLE', 'Ek server UNREACHABLE hai', 'In ~/ans, ansible all -m ping reaches web01.lab.local but db01 is UNREACHABLE. Find out why and fix it so that ping succeeds on both hosts. (Use the lab button.)', '~/ans mein ansible all -m ping web01.lab.local tak pahunchta hai par db01 UNREACHABLE hai. Wajah dhundho aur theek karo taaki dono hosts par ping safal ho. (Lab button use karo.)', 'ansible all -m ping ; ssh-copy-id learner@db01 ; ansible all -m ping', 'ansible all -m ping ; ssh-copy-id learner@db01 ; ansible all -m ping', (sh) => { const pings = sh.log.filter((r) => /ansible\s+all.*-m\s+ping/.test(r.cmd)); const pub = LX.cat(sh, '/home/learner/.ssh/id_ed25519.pub').trim().split(' ').slice(0, 2).join(' '); const keys = ((sh.remoteAuth || {}).db01 || {}).learner || []; return pings.length >= 2 && keys.includes(pub) && pings[pings.length - 1].code === 0; }, UNREACH_LAB.concat(UNREACH_FIX), { lab: { setup: UNREACH_LAB, en: 'a project where the SSH key was installed on web01 only.', hi: 'project jahan SSH key sirf web01 par lagi hai.' }, testSolve: UNREACH_LAB.concat(UNREACH_FIX) }),
    ],
    quiz: [
      mcq(1, 'How does Ansible talk to the servers it manages?', 'Ansible apne managed servers se kaise baat karta hai?', ['With an agent that you install on every server', 'Over SSH, with no agent (it uses the Python that is already there)', 'Through a dedicated Ansible port 9999', 'By e-mail'], 1, 'Agentless: just SSH and Python on the managed nodes.', 'Agentless: managed nodes par bas SSH aur Python.'),
      mcq(2, 'What does "idempotent" mean for an Ansible task?', 'Ansible task ke liye "idempotent" ka kya matlab hai?', ['It always restarts the service', 'Running it again changes nothing if the system is already in the desired state', 'It runs only once per year', 'It cannot fail'], 1, 'Declare the state, not the steps: re-running is safe.', 'Steps nahi, halat batao: dobara chalana surakshit hai.'),
      cmd(3, 'Ping all hosts of the inventory in ~/ans with the ping module.', '~/ans ki inventory ke sab hosts ko ping module se ping karo.', { setup: LAB, cwd: '~/ans', verify: (sh, r) => (r.out.match(/pong/g) || []).length === 2, sample: 'ansible all -m ping', alt: ['ansible all -i inventory.ini -m ping', 'ansible prod -m ping', 'ansible all -m ansible.builtin.ping'], wrong: ['ansible web -m ping', 'ping web01.lab.local'], hintEn: 'ansible, the pattern for every host, -m and the module.', hintHi: 'ansible, har host ka pattern, -m aur module.' }, 'all is the built-in group of every host; two pongs mean SSH and Python work on both.', 'all har host ka built-in group hai; do pong matlab dono par SSH aur Python chalte hain.'),
      cmd(4, 'Run the command uptime on the hosts of the web group only.', 'Sirf web group ke hosts par uptime command chalao.', { setup: LAB, cwd: '~/ans', verify: (sh, r) => /web01\.lab\.local/.test(r.out) && !/db01/.test(r.out) && /load average/.test(r.out), sample: 'ansible web -a uptime', alt: ['ansible web -m command -a uptime', 'ansible web -m shell -a uptime', 'ansible all -a uptime --limit web'], wrong: ['ansible all -a uptime', 'ansible db -a uptime'], hintEn: 'The default module is command: only -a is needed.', hintHi: 'Default module command hai: sirf -a chahiye.' }, 'Without -m the command module runs; the pattern chooses the group.', '-m ke bina command module chalta hai; pattern group chunta hai.'),
      cmd(5, 'Install the package htop as root on the db group only (ad-hoc, apt module).', 'Sirf db group par root ki tarah htop package install karo (ad-hoc, apt module).', { setup: LAB, cwd: '~/ans', verify: (sh) => hasPkg(sh, 'db01', 'htop') && !hasPkg(sh, 'web01.lab.local', 'htop'), sample: 'ansible db -b -m apt -a "name=htop state=present"', alt: ['ansible db --become -m ansible.builtin.apt -a "name=htop state=present"', 'ansible db -b -m package -a "name=htop state=present"'], wrong: ['ansible all -b -m apt -a "name=htop state=present"', 'ansible db -m apt -a "name=htop state=present"'], hintEn: '-b becomes root; -m apt; -a name=... state=present.', hintHi: '-b root banata hai; -m apt; -a name=... state=present.' }, 'Without -b the apt module has no root rights and fails.', '-b ke bina apt module ke paas root adhikar nahi hote aur fail hota hai.'),
      cmd(6, 'Only check the syntax of the playbook site.yml (do not run it).', 'Sirf playbook site.yml ka syntax check karo (chalao mat).', { setup: LAB.concat(['cd ~/ans', here('site.yml', SITE)]), cwd: '~/ans', verify: (sh, r) => /playbook: site\.yml/.test(r.out) && !/PLAY \[/.test(r.out) && !hasPkg(sh, 'web01.lab.local', 'nginx'), sample: 'ansible-playbook --syntax-check site.yml', alt: ['ansible-playbook site.yml --syntax-check'], wrong: ['ansible-playbook site.yml', 'ansible-playbook --check site.yml'], hintEn: 'ansible-playbook with the syntax flag.', hintHi: 'ansible-playbook, syntax flag ke saath.' }, '--syntax-check parses the playbook and stops before connecting to any host.', '--syntax-check playbook parse karta hai aur kisi host se jodne se pehle ruk jata hai.'),
      cmd(7, 'Do a dry run of site.yml: show what would change without changing anything.', 'site.yml ka dry run karo: dikhao kya badlega, kuch badle bina.', { setup: LAB.concat(['cd ~/ans', here('site.yml', SITE)]), cwd: '~/ans', verify: (sh, r) => /PLAY RECAP/.test(r.out) && !hasPkg(sh, 'web01.lab.local', 'nginx'), sample: 'ansible-playbook --check site.yml', alt: ['ansible-playbook -C site.yml', 'ansible-playbook site.yml --check --diff', 'ansible-playbook site.yml -C'], wrong: ['ansible-playbook site.yml', 'ansible-playbook --syntax-check site.yml'], hintEn: 'The check flag.', hintHi: 'Check flag.' }, 'Check mode connects, evaluates every task and reports changed/ok but does not apply anything.', 'Check mode connect karta hai, har task evaluate karta hai aur changed/ok batata hai par kuch lagu nahi karta.'),
      cmd(8, 'Run site.yml but only on the host web01.lab.local (the play targets web).', 'site.yml chalao par sirf host web01.lab.local par (play web ko target karta hai).', { setup: LAB.concat(['cd ~/ans', here('site.yml', SITE.map((l) => l.replace('hosts: web', 'hosts: prod')))]), cwd: '~/ans', verify: (sh, r) => hasPkg(sh, 'web01.lab.local', 'nginx') && !hasPkg(sh, 'db01', 'nginx') && /web01\.lab\.local\s+:\s+ok=/.test(r.out) && !/db01\s+:\s+ok=/.test(r.out), sample: 'ansible-playbook site.yml --limit web01.lab.local', alt: ['ansible-playbook site.yml -l web01.lab.local', 'ansible-playbook -l web01.lab.local site.yml', 'ansible-playbook site.yml --limit web'], wrong: ['ansible-playbook site.yml', 'ansible-playbook site.yml --limit db01'], hintEn: '--limit takes a host or group pattern.', hintHi: '--limit host ya group pattern leta hai.' }, '--limit narrows the play\'s hosts: the safe way to try a change on one canary server.', '--limit play ke hosts kam karta hai: ek canary server par badlav try karne ka surakshit tareeka.'),
      mcq(9, 'Why is  ansible.builtin.apt: name=nginx state=present  better than  shell: apt-get install -y nginx ?', 'ansible.builtin.apt: name=nginx state=present, shell: apt-get install -y nginx se behtar kyun hai?', ['It is shorter to type', 'The module checks the current state, only acts if needed and reports changed accurately (idempotent)', 'shell is not allowed over SSH', 'apt-get cannot install nginx'], 1, 'Modules are idempotent and report truthfully; shell runs blindly every time.', 'Modules idempotent hain aur sach batate hain; shell har baar andha chalta hai.'),
      cmd(10, 'Boss level: with ONE ad-hoc command create the directory /opt/app on the web group, as root, with mode 0750.', 'Boss level: EK ad-hoc command se web group par root ki tarah directory /opt/app mode 0750 ke saath banao.', { setup: LAB, cwd: '~/ans', verify: (sh) => { const n = host(sh, 'web01.lab.local').fs.lookup('/opt/app'); return !!n && n.t === 'd' && (n.mode & 0o777) === 0o750 && !host(sh, 'db01').fs.lookup('/opt/app'); }, sample: 'ansible web -b -m file -a "path=/opt/app state=directory mode=0750"', alt: ['ansible web --become -m ansible.builtin.file -a "path=/opt/app state=directory mode=0750"', 'ansible web -b -m file -a "path=/opt/app mode=0750 state=directory"'], wrong: ['ansible web -b -m file -a "path=/opt/app state=directory"', 'ansible all -b -m file -a "path=/opt/app state=directory mode=0750"'], hintEn: 'The file module with state=directory and a mode.', hintHi: 'file module, state=directory aur mode ke saath.' }, 'The file module creates directories idempotently and sets the mode; -b is needed to write in /opt.', 'file module directories idempotent tareeke se banata hai aur mode set karta hai; /opt mein likhne ko -b chahiye.'),
    ],
  });
})();
